86	    } else if (idlePeriodStartNanos == 0) {
87	      idlePeriodStartNanos = System.nanoTime();
88	    } else if ((System.nanoTime() - idlePeriodStartNanos) > idleReportingPeriodNanos) {
89	      // increment the counter and reset the start of the idle period.
90	      processMetrics.incrementIdleCounter();
91	      idlePeriodStartNanos = 0;
92	    } else {
93	      // idleStartPeriod is non-zero, but we have not hit the idleStopPeriod yet
94	    }
