47	public class MetricsUtil {
48	
49	  private static final Logger LOG = LoggerFactory.getLogger(MetricsUtil.class);
50	
51	  private static JvmGcMetrics gc;
52	  private static List<Tag> commonTags;
53	  private static Pattern camelCasePattern = Pattern.compile("[a-z][A-Z][a-z]");
54	
55	  public static void initializeMetrics(final AccumuloConfiguration conf, final String appName,
56	      final HostAndPort address, final String instanceName, final String resourceGroup)
57	      throws ClassNotFoundException, InstantiationException, IllegalAccessException,
58	      IllegalArgumentException, InvocationTargetException, NoSuchMethodException,
59	      SecurityException {
60	    initializeMetrics(conf.getBoolean(Property.GENERAL_MICROMETER_ENABLED),
61	        conf.getBoolean(Property.GENERAL_MICROMETER_JVM_METRICS_ENABLED),
62	        conf.get(Property.GENERAL_MICROMETER_FACTORY), appName, address, instanceName,
63	        resourceGroup, conf.get(Property.GENERAL_MICROMETER_USER_TAGS));
64	  }
65	
66	  private static void initializeMetrics(boolean enabled, boolean jvmMetricsEnabled,
67	      String factoryClass, String appName, HostAndPort address, String instanceName,
68	      String resourceGroup, String userTags) throws ClassNotFoundException, InstantiationException,
69	      IllegalAccessException, IllegalArgumentException, InvocationTargetException,
70	      NoSuchMethodException, SecurityException {
71	
72	    LOG.info("initializing metrics, enabled:{}, class:{}", enabled, factoryClass);
73	
74	    if (enabled && factoryClass != null && !factoryClass.isEmpty()) {
75	
76	      String processName = appName;
77	      String serviceInstance = System.getProperty("accumulo.metrics.service.instance", "");
78	      if (!serviceInstance.isBlank()) {
79	        processName += serviceInstance;
80	      }
81	
82	      List<Tag> tags = new ArrayList<>();
83	      tags.add(Tag.of("instance.name", instanceName));
84	      tags.add(Tag.of("process.name", processName));
85	      tags.add(Tag.of("resource.group", resourceGroup));
86	      if (address != null) {
87	        if (!address.getHost().isEmpty()) {
88	          tags.add(Tag.of("host", address.getHost()));
89	        }
90	        if (address.getPort() > 0) {
91	          tags.add(Tag.of("port", Integer.toString(address.getPort())));
92	        }
93	      }
94	
95	      if (!userTags.isEmpty()) {
96	        String[] userTagList = userTags.split(",");
97	        for (String userTag : userTagList) {
98	          String[] tagParts = userTag.split("=");
99	          if (tagParts.length == 2) {
100	            tags.add(Tag.of(tagParts[0], tagParts[1]));
101	          } else {
102	            LOG.warn("Malformed user metric tag: {} in property {}", userTag,
103	                Property.GENERAL_MICROMETER_USER_TAGS.getKey());
104	          }
105	        }
106	      }
107	
108	      commonTags = Collections.unmodifiableList(tags);
109	
110	      Class<? extends MeterRegistryFactory> clazz =
111	          ClassLoaderUtil.loadClass(factoryClass, MeterRegistryFactory.class);
112	      MeterRegistryFactory factory = clazz.getDeclaredConstructor().newInstance();
113	
114	      MeterRegistry registry = factory.create();
115	      registry.config().commonTags(commonTags);
116	      Metrics.addRegistry(registry);
117	
118	      if (jvmMetricsEnabled) {
119	        new ClassLoaderMetrics(commonTags).bindTo(Metrics.globalRegistry);
120	        new JvmMemoryMetrics(commonTags).bindTo(Metrics.globalRegistry);
121	        gc = new JvmGcMetrics(commonTags);
122	        gc.bindTo(Metrics.globalRegistry);
123	        new ProcessorMetrics(commonTags).bindTo(Metrics.globalRegistry);
124	        new JvmThreadMetrics(commonTags).bindTo(Metrics.globalRegistry);
125	      }
126	    }
127	  }
128	
129	  public static void initializeProducers(MetricsProducer... producer) {
130	    for (MetricsProducer p : producer) {
131	      p.registerMetrics(Metrics.globalRegistry);
132	      LOG.info("Metric producer {} initialized", p.getClass().getSimpleName());
133	    }
134	  }
135	
136	  public static void addExecutorServiceMetrics(ExecutorService executor, String name) {
137	    new ExecutorServiceMetrics(executor, name, commonTags).bindTo(Metrics.globalRegistry);
138	  }
139	
140	  public static List<Tag> getCommonTags() {
141	    return commonTags;
142	  }
143	
144	  /**
145	   * Centralize any specific string formatting for metric names and/or tags. Ensure strings match
146	   * the micrometer naming convention.
147	   */
148	  public static String formatString(String name) {
149	
150	    // Handle spaces
151	    name = name.replace(" ", ".");
152	    // Handle snake_case notation
153	    name = name.replace("_", ".");
154	    // Handle Hyphens
155	    name = name.replace("-", ".");
156	
157	    // Handle camelCase notation
158	    Matcher matcher = camelCasePattern.matcher(name);
159	    StringBuilder output = new StringBuilder(name);
160	    int insertCount = 0;
161	    while (matcher.find()) {
162	      // Pattern matches at a lowercase letter, but the insert is at the second position.
163	      output.insert(matcher.start() + 1 + insertCount, ".");
164	      // The correct index position will shift as inserts occur.
165	      insertCount++;
166	    }
167	    name = output.toString();
168	    return name.toLowerCase();
169	  }
